UPDATE inscription SET plan_paiement_id = 2 WHERE id IN (1, 23, 41, 73, 105, 139, 169, 200, 231);

-- Un encaissement saisi en double, annulé par l'intendant : le reçu reste, les imputations sont retirées.
DELETE FROM imputation_paiement WHERE paiement_id = 1;
UPDATE echeance_eleve e SET montant_paye = COALESCE((SELECT sum(i.montant) FROM imputation_paiement i WHERE i.echeance_eleve_id = e.id), 0) WHERE e.frais_eleve_id IN (SELECT id FROM frais_eleve WHERE inscription_id = 1);
UPDATE echeance_eleve e SET statut = CASE WHEN e.montant_paye >= e.montant_du THEN 'PAYEE' WHEN e.date_echeance < DATE '2026-11-17' THEN 'EN_RETARD' WHEN e.montant_paye > 0 THEN 'PARTIEL' ELSE 'A_VENIR' END WHERE e.frais_eleve_id IN (SELECT id FROM frais_eleve WHERE inscription_id = 1);
UPDATE paiement SET statut = 'ANNULE', motif_annulation = 'Encaissement saisi deux fois le même jour', annule_par = 'intendant' WHERE id = 1;

